import Style from './FriendSearch.module.css';

import { useState, useMemo } from 'react';
import searchFriend from '../../api/search/friend/friend';
import { useAuth } from '../../context/AuthContext';

import friendAdd from '../../api/add/friend';

import FriendList from '../../component/main-component/FriendList';
import { profileImageUrl } from '../../utils/serverOrigin';

function formatJoinDate(createdAt) {
    if (!createdAt) return '—';
    const raw = String(createdAt);
    const datePart = raw.includes('T') ? raw.split('T')[0] : raw.slice(0, 10);
    const parts = datePart.split('-');
    if (parts.length < 3) return raw;
    const [y, m, d] = parts;
    return `${y}년 ${m}월 ${d}일`;
}

export default function FriendSearch({ setFriendChange, friendChange }) {
    const [email, setEmail] = useState('');
    const [result, setResult] = useState();

    const { userInfo } = useAuth();

    const searchFunction = async () => {
        const data = await searchFriend({ email });
        setResult(data);
    };

    const friendAddFunction = async (friend_id) => {
        const data = await friendAdd({ friend_id });
        if (data?.success === false) {
            alert(data.message);
        } else {
            alert(data.message);
            setFriendChange((value) => !value);
        }
    };

    const resultUser = result?.success ? result.data : null;
    const avatarSrc = useMemo(
        () => (resultUser ? profileImageUrl(resultUser.profile) : null),
        [resultUser]
    );

    return (
        <div className={Style.main_box}>
            {userInfo ? (
                <div className={Style.height_size}>
                    <div className={Style.size20}>
                        <FriendList friendChange={friendChange} setFriendChange={setFriendChange} />
                    </div>
                    <section className={Style.searchPanel} aria-label="친구 검색">
                        <div className={Style.searchHead}>
                            <h2 className={Style.searchTitle}>친구 찾기</h2>
                            <p className={Style.searchSubtitle}>이메일로 상대를 검색해 보세요.</p>
                        </div>

                        <div className={Style.searchBar}>
                            <div className={Style.inputWrap}>
                                <span className={Style.inputIcon} aria-hidden>
                                    ✉
                                </span>
                                <input
                                    type="search"
                                    className={Style.searchInput}
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter') searchFunction();
                                    }}
                                    placeholder="이메일 주소 입력"
                                    autoComplete="off"
                                />
                            </div>
                            <button type="button" className={Style.searchBtn} onClick={searchFunction}>
                                검색
                            </button>
                        </div>

                        <div className={Style.resultCard}>
                            {resultUser ? (
                                <div className={Style.userCard}>
                                    <div className={Style.userMain}>
                                        <img
                                            src={avatarSrc}
                                            alt=""
                                            className={Style.userAvatar}
                                        />
                                        <div className={Style.userMeta}>
                                            <span className={Style.userName}>{resultUser.username}</span>
                                            <span className={Style.userEmail}>{resultUser.email}</span>
                                            <span className={Style.userJoined}>
                                                가입일 {formatJoinDate(resultUser.created_at)}
                                            </span>
                                        </div>
                                    </div>
                                    <button
                                        type="button"
                                        className={Style.addBtn}
                                        onClick={() => friendAddFunction(resultUser.user_id)}
                                    >
                                        친구 추가
                                    </button>
                                </div>
                            ) : !result?.success && result ? (
                                <div className={Style.emptyState}>
                                    <p className={Style.emptyMsg}>{result?.message}</p>
                                </div>
                            ) : (
                                <div className={Style.emptyState}>
                                    <div className={Style.emptyIllustration} aria-hidden />
                                    <p className={Style.emptyHint}>검색어를 입력하고 검색해 보세요.</p>
                                </div>
                            )}
                        </div>
                    </section>
                </div>
            ) : null}
        </div>
    );
}
